use App\Models\WorkoutProgram;
use App\Models\WorkoutProgramExercise;
use Illuminate\Database\Seeder;

/**
 * Real starting content of the catalogue (not demo user data). Suggested sets/reps/rest are common
 * starting points, NOT prescriptions: they are never raised automatically (see docs/EXERCISES.md).
 * Images are generated by scripts/make-figures.mjs: public/images/exercises/{slug}-start|end.svg
 */
class ExerciseSeeder extends Seeder
{
    private int $sort = 0;

    /** @param array<int,array{0:int,1:int,2:int}> $rx [sets, reps|seconds, rest] for beginner, intermediate, advanced */
    private function ex(string $slug, string $name, string $cat, string $grp, array $muscles, string $level, array $equip, string $kind, array $steps, string $breathing, array $mistakes, string $precautions, string $easier, array $rx): void
    {
        $keys = ['beginner', 'intermediate', 'advanced'];
        $presc = [];
        foreach ($rx as $i => [$sets, $val, $rest]) {
            $presc[$keys[$i]] = ['sets' => $sets, $kind === 'time' ? 'seconds' : 'reps' => $val, 'rest' => $rest];
        }
        Exercise::updateOrCreate(['slug' => $slug], [
            'name' => $name, 'category' => $cat, 'muscle_group' => $grp, 'muscles' => $muscles, 'level' => $level, 'equipment' => $equip,
            'kind' => $kind, 'steps' => $steps, 'breathing' => $breathing, 'mistakes' => $mistakes, 'precautions' => $precautions,
            'easier_variant' => $easier, 'prescriptions' => $presc,
            'image_start' => "/images/exercises/{$slug}-start.svg", 'image_end' => "/images/exercises/{$slug}-end.svg", 'sort' => $this->sort++,
        ]);
    }

