                [['squat', 2, 8, null, 60], ['pompes-genoux', 2, 6, null, 60], ['pont-fessier', 2, 10, null, 45], ['superman', 2, 8, null, 45], ['gainage-ventral', 2, null, 15, 45]]],
            ['Abdominaux et stabilité du tronc', 'abs', 'beginner', 'Gainage et contrôle du tronc, progressif et sans élan.', ['none'], ['abdominaux'],
                [['dead-bug', 2, 6, null, 45], ['bird-dog', 2, 6, null, 45], ['crunch', 2, 8, null, 45], ['gainage-ventral', 2, null, 20, 45], ['releves-genoux', 2, 6, null, 45]]],
            ['Haut du corps', 'strength', 'intermediate', 'Pectoraux, dos, épaules et bras. Haltères ou élastique facultatifs.', ['dumbbells', 'bands'], ['pectoraux', 'dos', 'epaules', 'biceps_triceps'],
                [['pompes-inclinees', 3, 10, null, 60], ['rowing-halteres', 3, 10, null, 60], ['developpe-epaules', 3, 10, null, 60], ['curl-biceps', 3, 10, null, 45], ['dips-chaise', 2, 8, null, 60]]],
            ['Jambes et fessiers', 'strength', 'beginner', 'Cuisses et fessiers, sans matériel.', ['none', 'wall'], ['jambes', 'fessiers'],
                [['squat', 3, 10, null, 60], ['fentes', 2, 6, null, 60], ['pont-fessier', 3, 12, null, 45], ['donkey-kick', 2, 10, null, 45], ['chaise-murale', 2, null, 20, 60]]],
            ['Mobilité et étirements (court)', 'mobility', 'beginner', 'Une séance douce de quelques minutes pour assouplir le corps.', ['none'], ['mobilite'],
                [['chat-vache', 1, 8, null, 10], ['rotation-thoracique', 1, 6, null, 10], ['etirement-quadriceps', 1, null, 20, 10], ['etirement-ischios', 1, null, 20, 10], ['posture-enfant', 1, null, 30, 10]]],
        ];
        foreach ($defs as [$name, $goal, $level, $desc, $equip, $groups, $items]) {
            $p = WorkoutProgram::firstOrNew(['name' => $name, 'is_template' => true]);
            $p->forceFill(['user_id' => null, 'is_template' => true, 'goal' => $goal, 'level' => $level, 'description' => $desc, 'equipment' => $equip, 'muscle_groups' => $groups])->save();
            $p->items()->delete();
            foreach ($items as $pos => [$slug, $sets, $reps, $secs, $rest]) {
                $p->items()->create(['exercise_id' => $id($slug), 'position' => $pos, 'sets' => $sets, 'reps' => $reps, 'seconds' => $secs, 'rest_seconds' => $rest]);
            }
            $p->load('items');
            $p->forceFill(['target_minutes' => $p->estimatedMinutes()])->save();
        }
    }
}
